  Let lo : Z := bv_unsigned sp0 - 128 - ATR_STACK.
  Let Elo : lo = bv_unsigned sp0 - 128 - 65536. Proof. reflexivity. Qed.
  Let COSTS : cost_laws H. Proof. exact (ah_costs H HH). Qed.

  Lemma aceil_loT : aceil + 4096 <= lo.
Proof.
